"OLAYLAR_ORTACAG_ORTADOGU:0813-09-24:0":{"b": ["Di dawiya dorpêça Bexdayê de Emîn hat kuştin (şeva 24 Muherem 198); Memûn derbasî xîlafetê bû.", "4fc1fe32"], "d": ["Di dawiya dorpêça Bexdayê de Emîn hat kuştin (şeva 24 Muherem 198); Memûn derbasî xîlafetê bû.", "4fc1fe32"]},
"OLAYLAR_ORTACAG_ORTADOGU:0815-08-11:0":{"b": ["Îbrahîm b. Mûsa Sana bi dest xist (200/815): Yemen ji destê walîyên Ebbasî derket", "49e27fe7"], "d": ["Serhildêrê Elewî Îbrahîm b. Mûsa yekîneyên ku Memûn şandibûn têk bir û Sana bi dest xist (200/815); heta ku Hemdeweyh b. Mahan ew têk bir û serxwebûna xwe îlan kir (203/818), bajar ji rêveberiya pratîk a Xîlafeta Ebbasî derket.", "dc150649"]},
"OLAYLAR_ORTACAG_ORTADOGU:0820-06-17:0":{"b": ["Îsa b. Yezîd el-Celûdî Hemdeweyh ji holê rakir (205/820): Sana vegeriya rêveberiya walîyên Ebbasî", "167a2fb1"], "d": ["Hemdeweyh b. Mahanê ku serxwebûna xwe îlan kiribû, ji aliyê Îsa b. Yezîd el-Celûdî ve hat ji holêrakirin (205/820); Sana û derdora wê heta sala 232 (847) ji aliyê walîyên Ebbasî yên ku ji Bexdayê dihatin şandin ve hatin rêvebirin. Bi vê dîrokê valahiya Sana ya di atlasê de (815-820) bi dawî dibe, serdema Xîlafeta Ebbasî dest pê dike.", "72c4a623"]},
"OLAYLAR_ORTACAG_ORTADOGU:0833-08-09:0":{"b": ["Memûn di sefera Bîzansê de nêzîkî Bedendûnê mir (18 Receb 218); birayê wî Mutesim bû xelîfe.", "fa3c1a4c"], "d": ["Memûn di sefera Bîzansê de nêzîkî Bedendûnê mir (18 Receb 218); birayê wî Mutesim bû xelîfe.", "fa3c1a4c"]},
"OLAYLAR_ORTACAG_ORTADOGU:0836-01-01:0":{"b": ["Mutesim Samerra ava kir û navenda xîlafetê bir wir.", "34873200"], "d": ["Mutesim Samerra ava kir û navenda xîlafetê bir wir.", "34873200"]},
"OLAYLAR_ORTACAG_ORTADOGU:0838-01-01:0":{"b": ["Mutesim ket Anatolyayê, Ammûriye (Amorion) dorpêç kir û zeft kir", "63534eea"], "d": ["Xelîfe Mutesim di 838an de bi artêşeke mezin ket Anatolyayê; bi rêya Enqereyê meşiya û Ammûriye, yek ji bajarên mezin ên Anatolyayê yê nêzîkî Afyonê, dorpêç kir û zeft kir.", "530472b7"]},
"OLAYLAR_ORTACAG_ORTADOGU:0868-09-15:0":{"b": ["Ahmed b. Tolûn wek wekîlê walî ket Misirê; bingehên Tolûnoxliyan hatin danîn", "7bfc6989"], "d": ["Ahmed b. Tolûn wek wekîlê walî ket Misirê; bingehên Tolûnoxliyan hatin danîn", "7bfc6989"]},
